  max_output_tokens: 30000
})));
for (let i = 0; i < rs.length; i++) {
  text(`QUERY ${qs[i]}\n${rs[i].output}`);
}

const qs = [
  "FiniteInAffine",
  "OrbitsInAffineOpen",
  "very ample",
  "quasi projective",
  "finite Galois base change",
  "group scheme affine open orbit"
];
const rs = await Promise.all(qs.map(q => tools.exec_command({
  cmd: `"$HORIZON_BIN" search ${JSON.stringify(q)} --json`,
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
  yield_time_ms: 30000,
  max_output_tokens: 30000
})));
for (let i = 0; i < rs.length; i++) {
  text(`QUERY ${qs[i]}\n${rs[i].output}`);
