  '"$HORIZON_BIN" search --name FiniteInAffine --limit 50 --json',
  '"$HORIZON_BIN" search --name OrbitsInAffineOpen --limit 50 --json',
  '"$HORIZON_BIN" search --name VeryAmple --limit 100 --json',
  '"$HORIZON_BIN" search --name QuasiProjective --limit 100 --json',
  '"$HORIZON_BIN" search --name IsProjective --limit 100 --json',
  '"$HORIZON_BIN" search --name baseChange --limit 100 --json'
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({
  cmd,
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge-Rebuild",
  yield_time_ms: 30000,
  max_output_tokens: 30000
})));
for (let i = 0; i < rs.length; i++) text(`CMD ${cmds[i]}\n${rs[i].output}`);

const calls = [
  ["sed -n '1,280p' AlgebraicJacobian/Albanese/StableAffineCoverGroup.lean", 30000],
  ["sed -n '130,260p' AlgebraicJacobian/Picard/PicEtPointedReduction.lean", 20000],
  ["sed -n '1,540p' AlgebraicJacobian/Picard/QuasiProjectiveFiniteInAffine.lean", 50000],
  ["sed -n '180,250p' AlgebraicJacobian/Picard/FiniteGaloisQuotient.lean", 15000],
  ["rg -n '^(def|class|structure|theorem|lemma|instance|abbrev) .*?(IsProjective|IsHQuasiProjective|VeryAmple|veryAmple|finiteInAffine|OrbitsInAffineOpen|baseChange|Group)' AlgebraicJacobian/Picard/ProjectiveMorphismBasic.lean AlgebraicJacobian/Picard/ProjectiveMorphism.lean AlgebraicJacobian/Picard/QuasiProjectiveFiniteInAffine.lean AlgebraicJacobian/Albanese/StableAffineCoverGroup.lean", 30000]
];
const rs = await Promise.all(calls.map(([cmd,max]) => tools.exec_command({
  cmd,
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge",
  yield_time_ms: 10000,
  max_output_tokens: max
})));
for (let i=0;i<rs.length;i++) text(`READ ${calls[i][0]}\n${rs[i].output}`);

const cmds = [
  '"$HORIZON_BIN" search --lib Algebraic-Jacobian-Challenge --name finiteInAffine --limit 200 --json | jq -c \'.[] | {name,signature,file,line,doc}\'',
  '"$HORIZON_BIN" search --lib Algebraic-Jacobian-Challenge --name GroupScheme --limit 200 --json | jq -c \'.[] | {name,signature,file,line,doc}\'',
  '"$HORIZON_BIN" search --lib Algebraic-Jacobian-Challenge --name affineOpen --limit 200 --json | jq -c \'.[] | select((.file|test(\"Albanese|Picard|Projective\"))) | {name,signature,file,line,doc}\'',
  '"$HORIZON_BIN" search --lib Algebraic-Jacobian-Challenge --name isAlgClosed --limit 200 --json | jq -c \'.[] | {name,signature,file,line,doc}\''
];
const rs = await Promise.all(cmds.map(cmd => tools.exec_command({
  cmd,
  workdir: "/home/axel/LeanAlgebraicGeometry-Horizon/MainProjects/Algebraic-Jacobian-Challenge",
  yield_time_ms: 30000,
  max_output_tokens: 40000
})));
for (let i=0;i<rs.length;i++) text(`SEARCH ${i+1}\n${rs[i].output}`);

